<script setup lang="ts">
import {ref,computed,watch} from 'vue';
import {control,currentMember,controlCommand,submitConfiguration} from '../services/control';
import type {Model} from '../../../../packages/api-client/src/control';
import {liveSelection} from '../services/live-selection';
import Modal from './Modal.vue';import Icon from './Icon.vue';
const creating=ref(false),selected=liveSelection(()=>control.programmes),name=ref(''),objective=ref(''),profile=ref(''),policy=ref(''),error=ref(''),busy=ref(false),key=ref('');
const sharing=ref(false),recipient=ref(''),permission=ref('read');
const currency=ref(''),model=ref(''),cpu=ref(''),gpu=ref(''),elapsed=ref('');
let profileRef:Model<'Ref'>|undefined,policyRef:Model<'Ref'>|undefined;
const canCreate=computed(()=>currentMember.value?.access_role==='owner'&&control.commands.includes('programme.create'));
function spend(value:string){const padded=value.padStart(7,'0');return padded.slice(0,-6)+'.'+padded.slice(-6).replace(/0+$/,'').padEnd(2,'0');}
function open(){creating.value=true;error.value='';key.value=crypto.randomUUID();profileRef=undefined;policyRef=undefined;}
watch(()=>control.workspace?.id,()=>{creating.value=false;selected.value=undefined;});
async function file(event:Event,kind:'profile'|'policy'){const input=(event.target as HTMLInputElement).files?.[0];if(!input)return;if(input.size>65536){error.value='Choose a configuration smaller than 64 KiB.';return;}const text=await input.text();try{JSON.parse(text);if(kind==='profile'){profile.value=text;profileRef=undefined;}else{policy.value=text;policyRef=undefined;}}catch{error.value='Choose a valid JSON configuration.';}}
async function save(){busy.value=true;error.value='';try{
 if(!profile.value||!policy.value)throw new Error('Choose a computational profile and gate policy.');
 profileRef??=await submitConfiguration('domain-profile',profile.value);policyRef??=await submitConfiguration('gate-policy',policy.value);
 await controlCommand('programme.create',{name:name.value,objective:objective.value,profile_ref:profileRef,initial_policy_refs:[policyRef],budget_ceiling:{currency:currency.value,model_microunits:model.value,cpu_milliseconds:cpu.value,gpu_milliseconds:gpu.value,elapsed_milliseconds:elapsed.value}},[],key.value);
 creating.value=false;
 }catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function share(){if(!selected.value)return;busy.value=true;error.value='';try{const subject={kind:'programme',id:selected.value.id,revision:selected.value.revision};const caps=permission.value==='none'?[]:permission.value==='read'?['read']:['read','comment','edit'];const sealed=await submitConfiguration('grant-changes',JSON.stringify({subject_ref:subject,changes:[{user_id:recipient.value,capabilities:caps}]}));await controlCommand('access.change',{subject_ref:subject,grant_changes_ref:sealed},[subject]);selected.value=control.programmes.find(p=>p.id===subject.id);sharing.value=false;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template>
<section class="programmes">
 <button v-if="canCreate" class="button primary new-research" @click="open"><Icon name="plus"/>New research</button>
 <div v-if="!control.programmes.length" class="center-empty"><h2>No projects yet</h2><button v-if="canCreate" class="button" @click="open">Create your first research</button><p v-else>No researches are shared with you.</p></div>
 <div v-else class="programme-list"><button v-for="item in control.programmes" :key="item.id" @click="selected=item"><Icon name="folder" :size="22"/><span><strong>{{item.name}}</strong><small>{{item.objective}}</small></span></button></div>
 <Modal v-if="creating" title="New research" @close="!busy&&(creating=false)"><form class="research-form" @submit.prevent="save"><header><span>{{control.workspace?.name}} · New research</span><button class="icon-button" type="button" aria-label="Close" :disabled="busy" @click="creating=false"><Icon name="close"/></button></header>
 <input v-model="name" class="research-title" aria-label="Research title" placeholder="Research title" maxlength="120" required autofocus :disabled="busy"/>
 <textarea v-model="objective" aria-label="Research objective" placeholder="Describe the research objective…" maxlength="10000" required :disabled="busy"/>
 <details open><summary>Scientific scope and budget</summary><p>Creation pins these configurations and records your initial ceiling. It does not start an inquiry.</p>
 <label>Computational profile (JSON)<input type="file" accept=".json,application/json" :disabled="busy" @change="file($event,'profile')"/></label>
 <label>Gate policy (JSON)<input type="file" accept=".json,application/json" :disabled="busy" @change="file($event,'policy')"/></label>
 <div class="budget-fields"><label>Currency<input v-model="currency" placeholder="EUR" pattern="[A-Z]{3}" required :disabled="busy"/></label><label>Model spend (millionths of currency)<input v-model="model" inputmode="numeric" pattern="0|[1-9][0-9]*" required :disabled="busy"/></label><label>CPU milliseconds<input v-model="cpu" inputmode="numeric" pattern="0|[1-9][0-9]*" required :disabled="busy"/></label><label>GPU milliseconds<input v-model="gpu" inputmode="numeric" pattern="0|[1-9][0-9]*" required :disabled="busy"/></label><label>Elapsed milliseconds<input v-model="elapsed" inputmode="numeric" pattern="0|[1-9][0-9]*" required :disabled="busy"/></label></div></details>
 <p v-if="error" class="form-error" role="alert">{{error}}</p><footer><button class="button primary" :disabled="busy||!profile||!policy">{{busy?'Creating…':'Create research'}}</button></footer></form></Modal>
 <Modal v-if="selected" :title="selected.name" @close="selected=undefined"><article class="research-form"><header><h2>{{selected.name}}</h2><button class="icon-button" aria-label="Close" @click="selected=undefined"><Icon name="close"/></button></header><p>{{selected.objective}}</p><h3>Standing constraints</h3><p>Computational research · {{selected.policy_refs.length}} pinned gate policy</p><dl class="budget-summary"><dt>Model spend ceiling</dt><dd>{{selected.budget_ceiling.currency}} {{spend(selected.budget_ceiling.model_microunits)}}</dd><dt>CPU time</dt><dd>{{selected.budget_ceiling.cpu_milliseconds}} ms</dd><dt>GPU time</dt><dd>{{selected.budget_ceiling.gpu_milliseconds}} ms</dd><dt>Elapsed time</dt><dd>{{selected.budget_ceiling.elapsed_milliseconds}} ms</dd></dl><template v-if="canCreate"><h3>Shared access</h3><p v-for="grant in control.grants.filter(g=>g.programme_id===selected?.id&&g.capabilities.length)" :key="grant.user_id">{{control.members.find(m=>m.user_id===grant.user_id)?.display_name||grant.user_id}} · {{grant.capabilities.join(', ')}}</p><button class="button" @click="sharing=!sharing;error=''">Manage access</button><form v-if="sharing" @submit.prevent="share"><label>Colleague<select v-model="recipient" required :disabled="busy"><option value="" disabled>Select a colleague</option><option v-for="member in control.members" :key="member.id" :value="member.user_id">{{member.display_name}}</option></select></label><label>Access<select v-model="permission" :disabled="busy"><option value="read">Read</option><option v-if="control.members.find(m=>m.user_id===recipient)?.access_role!=='viewer'" value="edit">Read, comment and edit</option><option value="none">Remove access</option></select></label><p>This applies only to this research. It grants no execution or scientific approval authority.</p><button class="button primary" :disabled="busy||!recipient">{{busy?'Saving…':'Confirm access'}}</button></form></template><p v-if="error" class="form-error" role="alert">{{error}}</p><p>Inquiry creation becomes available when admission and funding gates are implemented.</p></article></Modal>
</section>
</template>
<style scoped>
.programmes{flex:1;min-height:0;overflow:auto}.new-research{position:absolute;right:20px;top:12px}.programme-list{padding:12px 28px}.programme-list>button{display:flex;align-items:center;gap:12px;padding:14px 0;width:100%;text-align:left;border-bottom:1px solid var(--border);font-size:14px}.programme-list small{display:block;margin-top:6px;color:var(--muted)}.research-form{padding:24px;display:grid;gap:16px;max-height:85vh;overflow:auto}.research-form header{display:flex;justify-content:space-between;align-items:center;font-size:13px;color:var(--muted)}.research-form .research-title{font-size:22px;font-weight:600;border:0}.research-form input,.research-form textarea,.research-form select{font:inherit;padding:8px;border:1px solid var(--border);border-radius:6px;background:var(--surface);color:var(--text);width:100%;min-width:0}.research-form textarea{min-height:80px;border:0;resize:vertical}.research-form label{display:grid;gap:6px;font-size:12px;margin-top:12px}.budget-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.research-form p{font-size:13px;color:var(--muted);line-height:20px}.research-form footer{display:flex;justify-content:flex-end}.research-form summary{font-size:14px;cursor:pointer}.budget-summary{display:grid;grid-template-columns:1fr auto;gap:10px;font-size:13px}.budget-summary dt{color:var(--muted)}.budget-summary dd{margin:0;font-variant-numeric:tabular-nums}
</style>
